# EXACT Bell optimum at N=8 (k=3, 64 points) for small q: orbit reps of Fourier supports S (0 in S WLOG by twisted
# translation) under O^+(6,2) (|.|=40320, generated by transvections), and exact max-agreement by enumerating
# (q-1)-subsets of points -> 2-dim nullspace of augmented rows [M(z), -beta(z)] -> max projective multiplicity.
import numpy as np, itertools, sys, time, math
from bell import beta, charmat
from oqgrp import oq_perms
k=3; n=64
P=oq_perms(k)                    # (40320, 64) permutations of F2^6
b=beta(k)
def canon(S):
    A=np.sort(P[:,list(S)],axis=1)
    # lexicographic min row
    idx=np.lexsort(A.T[::-1]); return tuple(A[idx[0]])
def reps(qq):
    R={ (0,) }
    for size in range(2,qq+1):
        new=set()
        for S in R:
            for v in range(1,n):
                if v in S: continue
                new.add(canon(S+(v,)))
        R=new
    return sorted(R)
def max_agree(S, rng=np.random.default_rng(1)):
    q=len(S); M=charmat(k,list(S)).astype(np.int64)
    R=np.concatenate([M,-b[:,None]],axis=1)            # rows R(z), want R(z).(x,1)=0
    best=-1; bestY=None
    combs=np.array(list(itertools.combinations(range(n),q-1)),dtype=np.int64)
    ra=rng.integers(-3,4,size=q+1); rb=rng.integers(-3,4,size=q+1)
    for c0 in range(0,len(combs),20000):
        C=combs[c0:c0+20000]; A=R[C]                    # (m, q-1, q+1)
        Ys=[]
        for r in (ra,rb):
            Aug=np.concatenate([A,np.broadcast_to(r,(len(C),1,q+1))],axis=1).astype(float)  # (m,q,q+1)
            y=np.empty((len(C),q+1))
            for j in range(q+1):
                sub=np.delete(Aug,j,axis=2); y[:,j]=(-1)**j*np.linalg.det(sub)
            Ys.append(np.rint(y).astype(np.int64))
        y1,y2=Ys
        # skip if not independent (rank(A)<q-1 or degenerate)
        u=R@y1.T; v=R@y2.T                                   # (64, m)
        u=u.T; v=v.T                                         # (m,64)
        always=(u==0)&(v==0)
        # projective point of hyperplane z on pencil: alpha*u + beta*v = 0 -> (alpha,beta) ~ (v,-u)
        g=np.gcd(u,v); g[g==0]=1
        a=v//g; bb=-u//g
        sgn=np.where((a<0)|((a==0)&(bb<0)),-1,1); a*=sgn; bb*=sgn
        # last coordinate of y = alpha*y1[q]+beta*y2[q] must be nonzero: excluded point (alpha,beta) ~ (y2[q],-y1[q])
        ea=y2[:,q:q+1]; eb=-y1[:,q:q+1]; ge=np.gcd(ea,eb); ge[ge==0]=1; ea=ea//ge; eb=eb//ge
        se=np.where((ea<0)|((ea==0)&(eb<0)),-1,1); ea*=se; eb*=se
        key=a*100003+bb
        bad=(key==ea*100003+eb)|always
        key=np.where(bad, -10**12-np.arange(n)[None,:], key)   # unique dummies
        ks=np.sort(key,axis=1)
        # max run length per row
        m_,L=ks.shape
        eq=np.concatenate([np.zeros((m_,1),bool),ks[:,1:]==ks[:,:-1]],axis=1)
        # run lengths: count consecutive trues
        run=np.zeros((m_,L),np.int64)
        for j in range(1,L): run[:,j]=np.where(eq[:,j],run[:,j-1]+1,0)
        run[ks<-10**11]=-1
        mx=run.max(axis=1)+1
        Y1=y1[:,:,None]*y2[:,None,:]; Dm=Y1-Y1.transpose(0,2,1)
        indep=np.any(Dm.reshape(len(C),-1)!=0,axis=1) & ~((y1[:,q]==0)&(y2[:,q]==0))
        tot=np.where(indep, mx+always.sum(axis=1), 0)
        i=int(np.argmax(tot))
        if tot[i]>best:
            # exact verification: recover y on the winning pencil point
            j=int(np.argmax(run[i])); kk=ks[i,j]
            zz=int(np.where(key[i]==kk)[0][0]); al,be=int(a[i,zz]),int(bb[i,zz])
            y=al*y1[i]+be*y2[i]
            from fractions import Fraction
            x=[Fraction(int(y[t]),int(y[q])) for t in range(q)]
            agree=sum(1 for z in range(n) if sum(x[t]*int(M[z,t]) for t in range(q))==int(b[z]))
            assert agree==tot[i], (agree,tot[i])
            best=int(tot[i]); bestY=(C[i].tolist(),[str(t) for t in x])
    return best,bestY
if __name__=='__main__':
    qq=int(sys.argv[1]); part=int(sys.argv[2]); nparts=int(sys.argv[3])
    if True:
        t0=time.time(); RS=reps(qq)
        print(f'q={qq}: {len(RS)} orbit reps (S containing 0, mod O(Q)); {time.time()-t0:.0f}s',flush=True)
        bestp=None
        for S in RS[part::nparts]:
            a,_=max_agree(S); p=n-a
            if bestp is None or p<bestp[0]: bestp=(p,S)
            print('  rep',[int(t) for t in S],'p',p,f'{time.time()-t0:.0f}s',flush=True)
        print(f'q={qq}: EXACT p_min = {bestp[0]} (S={bestp[1]}) {time.time()-t0:.0f}s',flush=True)
